// LED yak söndür: 9. pindeki LED saniyede bir yanıp söner.
const int LED_PIN = 9;

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_PIN, HIGH);
  Serial.println("Yandi");
  delay(1000);
  digitalWrite(LED_PIN, LOW);
  Serial.println("Sondu");
  delay(1000);
}
